insert into common_enum (enum_code, enum_name, enum_text,
parent_id, create_time, create_by
)
values (#{enumCode,jdbcType=VARCHAR}, #{enumName,jdbcType=VARCHAR}, #{enumText,jdbcType=VARCHAR},
#{parentId,jdbcType=BIGINT}, #{createTime,jdbcType=TIMESTAMP}, #{createBy,jdbcType=VARCHAR}
)

