SELECT b.id,b.enum_code,b.enum_name,b.enum_text,b.create_time,b.create_by,b.parent_id from common_enum b where b.parent_id = (SELECT a.id from common_enum a where a.enum_code = #{enumCode,jdbcType=VARCHAR})
and enum_name like concat('%',#{enumName,jdbcType=VARCHAR},'%')
limit #{pageIndex}, #{pageSize}
